import React from 'react';

import Anchor from '../../../partials/anchor';
import Name from '../../../partials/name';
import Paragraph from '../../../partials/paragraph';
import VersionTabs from '../../../partials/version-tabs';
import NotePad from '../../../partials/pad/note';

const ConceptClientPage : React.FC<{className? : string}> = ({ className }) => (
    <article className={ `concept-client-page ${ className }` }>
        <h1>Client</h1>
        <VersionTabs options={[{
            documentation: ( <BodyCurrent2_0 /> ),
            version: [ 2, 0, 0 ]
        }, {
            documentation: ( <BodyCurrent /> ),
            version: [ 1, 0, 0 ]
        }]} />
    </article>
);

export default ConceptClientPage;

function BodyCurrent() { return ( <Template /> ) }

function BodyCurrent2_0() {
    return (
        <Template
            additionalPropsDoc={
                <p>
                    <strong style={{ marginRight: '0.5rem' }}>4.</strong><strong style={{ marginRight: '0.25rem' }}><Anchor to="/concepts/selector-map">selectorMap</Anchor>: </strong>
                    exposes the underlying selector map through which this stream is supplied. The underlying selector map may be updated from this property.
                    <NotePad><b><u>Keep in mind</u>,</b> altering this property will affect all rendered elements of its <Anchor to="/concepts/client">client</Anchor>. Those elements will all begin to reflect output based on the new selector map.</NotePad>
                </p>
            }
            numProperties={ 4 }
        />
    );
}

function Template({
    additionalPropsDoc = null,
    numProperties = 3
} : {
    additionalPropsDoc? : React.ReactNode;
    numProperties? : number;
}) {
    return (
        <div>
            <h3>What is a client?</h3>
            <div>
                <Paragraph>
                    A client is any resource { "(" }i.e. component, service, directives etc.{ ")" }  consuming the <Name />. A client consumes this context by:
                    <ul>
                        <li>either injecting the <Name/>'s <code>ContextService</code> into a resource and accessing the context directly through this service as needed. More on this <Anchor to="/overview/direct-usage">here.</Anchor></li>
                        <li>or streaming it through a <Name />'s <code>StreamingService</code> instance. More on this <Anchor to="/overview/streaming">here.</Anchor></li>
                    </ul>
                </Paragraph>
                <Paragraph>
                    Please see specific code examples respectively in:
                    <ol>
                        <li><Anchor to="/getting-started#direct-usage">Direct Usage</Anchor></li>
                        <li><Anchor to="/getting-started#streaming">Joining the <Name /> Change Stream</Anchor></li>
                    </ol>
                </Paragraph>
            </div>
        </div>
    );
}
